# skillver <frontmatter-content> -> the version detect-ecosystem.sh reports
skillver() {
  printf '%s' "$1" >"$TMP/skills/demo/SKILL.md"
  (cd "$TMP" && bash "$DETECT" 2>/dev/null) |
    sed -n 's|^version-file:skills/demo/SKILL\.md:||p'
}
